export function localizeContentText(locale: ContentLocale, value: string) {
  return recurringTranslations[locale]?.[value] ?? value;
}

export function localizeAssessmentPrompt(locale: ContentLocale, prompt: string, dimensionKey?: string) {
  const translation = dimensionKey ? assessmentDimensionTranslations[locale]?.[dimensionKey] : undefined;
  if (!translation) return prompt;
  const match = prompt.match(/\s\(([^)]+)\)$/);
  return match ? `${prompt.slice(0, match.index)} (${translation})` : prompt;
}

function localizeLessonTitle(locale: ContentLocale, title: string) {
  return lessonTitleTranslations[locale]?.[title] ?? localizeContentText(locale, title);
}

function localizedLesson(locale: ContentLocale, lesson: CourseLesson, moduleIndex: number, lessonIndex: number): CourseLesson {
  const copy = longFormCopy[locale];
  const title = localizeLessonTitle(locale, lesson.title);
  const sections = lesson.sections.map((section, index) => ({
    ...section,
    heading: copy.headings[index] ?? localizeContentText(locale, section.heading),
    body: copy.sections[index] ?? section.body,
    callout: index < 2 ? copy.callouts[index] : undefined,
  }));
  return {
    ...lesson,
    title,
    summary: copy.summary,
    outcome: copy.outcome,
    objectives: copy.objectives,
    sections,
    example: { context: copy.example[0], move: copy.example[1], result: copy.example[2] },
    simulation: { prompt: copy.simulation.prompt, options: copy.simulation.options, feedback: copy.simulation.feedback },
    reflectionPrompt: copy.reflection,
    keyTakeaway: copy.takeaway,
    illustration: { ...lesson.illustration, label: `${copy.signal} ${String(moduleIndex + 1).padStart(2, "0")}.${lessonIndex + 1}`, caption: copy.caption },
  };
}

function localizedQuiz(locale: ContentLocale, question: CourseQuizQuestion, questionIndex: number, lessonTitle: string): CourseQuizQuestion {
  const copy = longFormCopy[locale];
  const correctIndex = Math.max(0, Math.min(3, question.correctOption));
  const options = [...copy.quizOptions];
  const correctAnswer = options.shift()!;
  options.splice(correctIndex, 0, correctAnswer);
  const feedback = [...copy.quizFeedback];
  const correctFeedback = feedback.shift()!;
  feedback.splice(correctIndex, 0, correctFeedback);
  return {
    ...question,
    prompt: copy.quizPrompts[questionIndex % copy.quizPrompts.length],
    options,
    correctOption: correctIndex,
    sourceLessonTitle: localizeLessonTitle(locale, lessonTitle),
    explanation: copy.quizExplanation,
    optionExplanations: feedback,
  };
}

export function localizeCourseDefinition(locale: ContentLocale, course: CourseDefinition): CourseDefinition {
  if (locale === "en") return course;
  const metadata = localizeCourseMetadata(locale, course.slug, course.title, course.description);
  return {
    ...course,
    title: metadata.title,
    description: metadata.description,
    modules: course.modules.map((module, moduleIndex) => ({
      ...module,
      title: localizeContentText(locale, module.title),
      promise: longFormCopy[locale].summary,
      lessons: module.lessons.map((lesson, lessonIndex) => localizedLesson(locale, lesson, moduleIndex, lessonIndex)),
      quiz: module.quiz.map((question, questionIndex) => localizedQuiz(locale, question, questionIndex, module.lessons[questionIndex % module.lessons.length]?.title ?? "Lesson")),
    })),
  };
}
